t.xp(225);assert.ok(t.get().heroes.every(h=>h.level===2&&h.sp===2));t.select(0);assert.ok(t.allocate('int'));assert.equal(t.get().heroes[0].int,1);assert.ok(t.allocate('dex'));assert.equal(t.allocate('int'),false,'Cannot spend without SP');
