c.setItem(0,'soul-fortune-1');assert.ok(c.moveItem({type:'bag',index:0},{type:'rune0',index:0}));assert.equal(c.dropMultiplier(),1.05);c.save();assert.ok(c.load());assert.equal(c.get().heroes[0].runes[0],'soul-fortune-1');assert.equal(c.dropMultiplier(),1.05);c.inspect('soul-fortune-1');assert.match(check.elements.get('#item-details').textContent,/Soul/);assert.equal(c.moveItem({type:'rune0',index:0},{type:'bag',index:1}),false);
c.get().heroes[0].hp=0;assert.equal(c.dropMultiplier(),1);check.math.random=()=>0;const boss=c.enemy('boss',300);const both=c.rollDrops(boss);assert.deepEqual(Array.from(both,id=>c.items[id].type),['weapon','rune','soul']);c.setArea(17);const late=c.rollDrops(c.enemy('boss',300));assert.equal(c.items[late.find(id=>c.items[id].type==='soul')].tier,5);
